export const item = pgTable(
  'item',
  {
    id: text().primaryKey().notNull(),
    name: text().notNull(),
    image: text().notNull(),
    tech: integer().notNull(),
    integrity: integer().notNull(),
    type: item_type().notNull(),
    min_damage: integer(),
    max_damage: integer(),
    damage_bonus: integer(),
    hands: integer(),
    reach: integer(),
    hits_per_round: integer(),
    created_at: timestamptz().default(sql`CURRENT_TIMESTAMP`),
    updated_at: timestamptz().default(sql`CURRENT_TIMESTAMP`),
    min_heal: integer(),
    max_heal: integer(),
  },
  (table) => [
    index('idx_item_tech').using(
      'btree',
      table.tech.asc().nullsLast().op('int4_ops'),
    ),
    index('idx_item_type').using(
      'btree',
      table.type.asc().nullsLast().op('enum_ops'),
    ),
    pgPolicy('Allow read item to authenticated users', {
      as: 'permissive',
      for: 'select',
      to: ['public'],
      using: sql`true`,
    }),
    check('valid_tech', sql`tech >= 0`),
    check('valid_integrity', sql`integrity >= 0`),
    check(
      'valid_damage_bonus',
      sql`(damage_bonus IS NULL) OR ((damage_bonus >= 0) AND (damage_bonus <= 5))`,
    ),
    check('valid_hands', sql`(hands IS NULL) OR (hands = ANY (ARRAY[1, 2]))`),
    check('valid_reach', sql`(reach IS NULL) OR (reach >= 0)`),
    check(
      'valid_hits_per_round',
      sql`(hits_per_round IS NULL) OR (hits_per_round > 0)`,
    ),
    check('valid_min_heal', sql`(min_heal IS NULL) OR (min_heal >= 0)`),
    check('valid_max_heal', sql`(max_heal IS NULL) OR (max_heal >= 0)`),
    check(
      'valid_heal_range',
      sql`((min_heal IS NULL) AND (max_heal IS NULL)) OR ((min_heal IS NOT NULL) AND (max_heal IS NOT NULL) AND (min_heal <= max_heal))`,
    ),
  ],
);

