export const subscription = pgTable(
  'subscription',
  {
    id: uuid().defaultRandom().primaryKey().notNull(),
    user_id: uuid().notNull(),
    plan_code: text().notNull(),
    plan_name: text().notNull(),
    price_cents: integer().notNull(),
    starts_at: timestamptz().notNull(),
    ends_at: timestamptz().notNull(),
    created_at: timestamptz().default(sql`CURRENT_TIMESTAMP`),
    updated_at: timestamptz().default(sql`CURRENT_TIMESTAMP`),
    status: text().default('pending').notNull(),
    validated_at: timestamptz(),
    validated_by: uuid(),
  },
  (table) => [
    index('idx_subscription_ends_at').using(
      'btree',
      table.ends_at.asc().nullsLast().op('timestamptz_ops'),
    ),
    index('idx_subscription_plan_code').using(
      'btree',
      table.plan_code.asc().nullsLast().op('text_ops'),
    ),
    index('idx_subscription_user_id').using(
      'btree',
      table.user_id.asc().nullsLast().op('uuid_ops'),
    ),
    index('idx_subscription_validated_by').using(
      'btree',
      table.validated_by.asc().nullsLast().op('uuid_ops'),
    ),
    foreignKey({
      columns: [table.user_id],
      foreignColumns: [usersInAuth.id],
      name: 'subscription_user_id_fkey',
    }).onDelete('cascade'),
    foreignKey({
      columns: [table.plan_code],
      foreignColumns: [subscription_plan.code],
      name: 'subscription_plan_code_fk',
    })
      .onUpdate('cascade')
      .onDelete('restrict'),
    foreignKey({
      columns: [table.validated_by],
      foreignColumns: [usersInAuth.id],
      name: 'subscription_validated_by_fkey',
    }),
    pgPolicy('Allow admin validate subscriptions', {
      as: 'permissive',
      for: 'update',
      to: ['public'],
      using: sql`(((( SELECT auth.jwt() AS jwt) -> 'app_metadata'::text) ->> 'role'::text) = 'admin'::text)`,
      withCheck: sql`(((( SELECT auth.jwt() AS jwt) -> 'app_metadata'::text) ->> 'role'::text) = 'admin'::text)`,
    }),
    pgPolicy('Allow user create own pending subscriptions', {
      as: 'permissive',
      for: 'insert',
      to: ['authenticated'],
    }),
    pgPolicy('Allow user read own subscriptions', {
      as: 'permissive',
      for: 'select',
      to: ['public'],
    }),
    check('valid_subscription_dates', sql`ends_at > starts_at`),
    check('valid_subscription_price', sql`price_cents > 0`),
    check(
      'valid_subscription_status',
      sql`status = ANY (ARRAY['pending'::text, 'validated'::text])`,
    ),
    check(
      'valid_subscription_validation_fields',
      sql`((status = 'pending'::text) AND (validated_at IS NULL) AND (validated_by IS NULL)) OR ((status = 'validated'::text) AND (validated_at IS NOT NULL))`,
    ),
  ],
);

